SELECT 
FROM show_session WHERE show_id = #{showId}
ORDER BY start_time ASC

SELECT 
FROM show_session

    AND show_id = #{showId}
    AND status = #{status}
    AND start_time >= #{startTime}
    AND start_time <= #{endTime}

ORDER BY start_time ASC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM show_session

    AND show_id = #{showId}
    AND status = #{status}
    AND start_time >= #{startTime}
    AND start_time <= #{endTime}
